const source = $('Build webhook request').item.json.dispatch_context;
const status = Number($json.statusCode ?? $json.httpCode ?? $json.error?.statusCode ?? $json.error?.httpCode ?? $json.error?.status ?? 0);
const detail = JSON.stringify($json.error ?? {}).toLowerCase();
let error_code = 'connection_failed';
if (status === 401 || status === 403) error_code = 'delivery_rejected';
else if (status === 429) error_code = 'rate_limited';
else if (status >= 400 && status < 500) error_code = 'http_4xx';
else if (status >= 500) error_code = 'http_5xx';
else if (detail.includes('timeout') || detail.includes('timed out')) error_code = 'timeout';
else if (detail.includes('credential')) error_code = 'credential_unavailable';
return {json:{delivery_result:{notification_id:source.notification_id,lease_token:source.lease_token,succeeded:false,response_status:status || null,response_excerpt:null,error_code}}};
